INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('080a0d4f9225a1a7', 'act_963898971023823', 'The Muni', 'Four new braided belts, $79.99, named for the public course. Film by Oct 20.', 'trees', '<path d="M10 10v.2A3 3 0 0 1 8.9 16H5a3 3 0 0 1-1-5.8V10a3 3 0 0 1 6 0Z"/><path d="M7 16v6"/><path d="M13 19v3"/><path d="M12 19h8.3a1 1 0 0 0 .7-1.7L18 14h.3a1 1 0 0 0 .7-1.7L16 9h.2a1 1 0 0 0 .8-1.7L13 3l-1.4 1.5"/>', '#1D4ED8', 1, 0, 1);
INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('d37d5dabe5edc438', 'act_963898971023823', 'Gifts (film them now)', 'Wives, kids and buddies shopping for the golfer who has everything. Live Nov 1 to Dec 20, so film in October.', 'gift', '<path d="M12 7v14"/><path d="M20 11v8a2 2 0 0 1-2 2H6a2 2 0 0 1-2-2v-8"/><path d="M7.5 7a1 1 0 0 1 0-5A4.8 8 0 0 1 12 7a4.8 8 0 0 1 4.5-5 1 1 0 0 1 0 5"/><rect x="3" y="7" width="18" height="4" rx="1"/>', '#15803D', 1, 0, 2);
INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('3396a97da88d8e0d', 'act_963898971023823', 'Holes are stupid', 'Cut once, click every 1/8 inch, and the old belt is the villain.', 'scissors', '<circle cx="6" cy="6" r="3"/><path d="M8.12 8.12 12 12"/><path d="M20 4 8.12 15.88"/><circle cx="6" cy="18" r="3"/><path d="M14.8 14.8 20 20"/>', '#BE123C', 1, 0, 3);
INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('82cb5e3f54740409', 'act_963898971023823', 'The belt people notice', 'Gator, ostrich, new drops, the compliment on the first tee.', 'gem', '<path d="M10.5 3 8 9l4 13 4-13-2.5-6"/><path d="M17 3a2 2 0 0 1 1.6.8l3 4a2 2 0 0 1 .013 2.382l-7.99 10.986a2 2 0 0 1-3.247 0l-7.99-10.986A2 2 0 0 1 2.4 7.8l2.998-3.997A2 2 0 0 1 7 3z"/><path d="M2 9h20"/>', '#0F766E', 1, 0, 4);
INSERT INTO p_amb_section (id, act_id, name, line, icon, icon_svg, color, enabled, pinned, sort) VALUES ('4cc063cb926a54e3', 'act_963898971023823', 'On the course this fall', 'Scrambles, trips, twilight nines and a real round where the belt does its job.', 'flag', '<path d="M4 22V4a1 1 0 0 1 .4-.8A6 6 0 0 1 8 2c3 0 5 2 7.333 2q2 0 3.067-.8A1 1 0 0 1 20 4v10a1 1 0 0 1-.4.8A6 6 0 0 1 16 16c-3 0-5-2-8-2a6 6 0 0 0-4 1.528"/>', '#B45309', 1, 0, 5);
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('b8855d58582a7c40', 'act_963898971023823', '080a0d4f9225a1a7', 1, 1, 1, 'live', 'Four belts, four kinds of golfer', 'The Muni line has four belts and each one is named for a kind of golfer. Say the name, show the belt, let them pick.', 'The public-course regular who buys gear with a story behind it.', 'The Muni: The Last Loop, Beach Club, Weekend Warrior, Tire Tracks', 'Fit check', NULL, '["Dartee named a belt after the guy whose Saturday tee time is the only appointment he''s made on time all week.", "Four new belts, four kinds of golfer. Which one are you?", "If you can still see the flag you can still play. That''s the rule, and that''s the belt."]', '[{"label": "Open · 0 to 3s", "text": "The four belts fanned out. Hand slides each into frame as you say the first line."}, {"label": "Middle", "text": "Put one on at a time, one line each: The Last Loop (first one out, last one in), Weekend Warrior (the Saturday appointment), Beach Club (the one everyone bought first), Tire Tracks (the cart path on 14)."}, {"label": "Close", "text": "Wearing your pick on the first tee. Ask which one they are."}]', 'Which Muni are you?', 'Use the names and stories exactly as the product pages have them.', 'Call it Skid Mark. The site says Tire Tracks now.', NULL, 'Four Muni belts fanned on the hood of the car or the cart seat. One hand slides each one into frame.', 'Each name gets its one-line story from the site, snap cut per belt. By belt three they are picking theirs.', 'Anson launched its new line by holding it to the lens and naming each colour; Pins and Aces fit checks name every piece on the course. A named line gives people a reason to film this week.', '[{"brand": "Anson Belt", "what": "Hold the new line to the lens, name each one, say it just came out.", "url": "https://app.tryatria.com/ad/m1102646692210777"}, {"brand": "Pins and Aces", "what": "A fit check on the course where you touch each piece as you name it.", "url": "https://app.tryatria.com/ad/m2302755733814212"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '08b9c54da36c14b9', 'act_963898971023823', 'b8855d58582a7c40', 'meta', '120246878327530741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120246878327530741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='b8855d58582a7c40' AND ad_id='120246878327530741');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '90a001bb693b4031', 'act_963898971023823', 'b8855d58582a7c40', 'meta', '120246878414970741', 1, 2 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120246878414970741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='b8855d58582a7c40' AND ad_id='120246878414970741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('8fe66c9b5ac647d4', 'act_963898971023823', '080a0d4f9225a1a7', 1, 2, 2, 'live', 'I bought a belt called Tire Tracks', 'The name is the joke and your buddies finish it for you.', 'Friend groups who give each other grief.', 'Tire Tracks (Muni)', 'Reaction', NULL, '["My belt is called Tire Tracks and my group will not let it go.", "Guess what this belt is named after.", "Dartee named this one after the cart path on 14 and honestly I feel seen."]', '[{"label": "Open · 0 to 3s", "text": "The belt and the name, held up. One line."}, {"label": "Middle", "text": "The buddy reaction, one take, no script. Then the cart corner, slow, tyre marks on the path."}, {"label": "Close", "text": "The other three names, one line each, then back on the belt."}]', 'Tire Tracks. Yes, really.', 'Real reaction. Do not tell the buddy the name first.', 'Drive fast for the joke.', NULL, 'Belt held up to the lens with the name visible on the tag or box. "Tire Tracks."', 'A buddy asks why. Cut to the cart taking the corner slow and the tyre marks on the path.', 'A funny name said three times is a rehook on its own. Groove ran a 15-second ad that just repeats "best belt in the world" and it sits at rank 3.', '[{"brand": "Bogey Bros", "what": "The \"let''s see how long it takes him to realize\" beat, here applied to a buddy reading the name.", "url": "https://app.tryatria.com/ad/m1859794814679897"}, {"brand": "Groove Life", "what": "Repeat the funny thing three times and let it carry the video.", "url": "https://app.tryatria.com/ad/m957958250525755"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('96bb2eda4798f21f', 'act_963898971023823', '080a0d4f9225a1a7', 0, 0, 3, 'live', 'Office at 9, nine holes at 5', 'One belt that looks right at the desk and on the first tee the same day.', 'The guy who plays after work in the same trousers he wore to the office.', 'The Muni (any)', 'Day in the life', NULL, '["I wore one belt from my 9am to my 5:30 tee time.", "Nobody at work knows this belt holds a ball marker.", "Office at nine. Nine holes at five. One belt."]', '[{"label": "Open · 0 to 3s", "text": "At the desk, belt in frame, time on screen. Say the line."}, {"label": "Middle", "text": "Walk out, bag in the car, first tee, pop the marker off at the first green."}, {"label": "Close", "text": "Sunset on the ninth. \"Still on.\""}]', '9 to 5, then 9 holes', 'Show the marker only once, on the green.', 'Film the office part for more than three seconds.', NULL, 'Office chair, belt in frame, the time on your phone screen. Cut straight to the car park.', 'Same belt, three places in ten seconds: desk, car, tee box. The marker comes off only once, on the first green.', 'The desk-to-twilight-nine golfer is who the apparel brands say they are dressing in 2026. Nobody has made the belt version.', '[{"brand": "Groove Life", "what": "Their copy sells \"comfortable from desk to dinner\". Make it desk to first tee.", "url": "https://app.tryatria.com/ad/m1009061838517746"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('1e6fff83f665c4ef', 'act_963898971023823', '080a0d4f9225a1a7', 0, 0, 4, 'live', 'A belt you forget you are wearing', 'A braided strap moves with the swing. You set it once and stop thinking about it.', 'Golfers who find a stiff leather belt bulky when they bend and turn.', 'The Muni (any)', 'Swing test', NULL, '["I didn''t notice this belt once in 18 holes, and that''s the whole point.", "Slow it down and watch the belt. Nothing moves.", "A belt that bends when you bend."]', '[{"label": "Open · 0 to 3s", "text": "The slow-mo swing from behind."}, {"label": "Middle", "text": "The three bends at real speed, 1, 2, 3 on screen."}, {"label": "Close", "text": "The ratchet setting on hole 1 and hole 18. Same click."}]', 'Set it once. Forgot it by hole 2.', 'Set it to fit, not tight, and leave it.', 'Say it fixes anything about the swing. And skip the word stretch for now.', NULL, 'Slow-motion driver swing from behind, belt dead centre of the frame, no talking yet.', 'Real speed, three bends in a row: tee it up, read a putt, climb out of a bunker. Count them on screen.', 'Anson''s creator videos all land on "it fits exactly where it should, every single time". A test you can see beats a claim you have to trust.', '[{"brand": "Anson Belt", "what": "A creator saying the belt fits the same every time, then proving it.", "url": "https://app.tryatria.com/ad/m1980515675946741"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'c4fff83fb516334f', 'act_963898971023823', '1e6fff83f665c4ef', 'meta', '120246878414970741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120246878414970741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='1e6fff83f665c4ef' AND ad_id='120246878414970741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('e85e6da5301a1ec5', 'act_963898971023823', '080a0d4f9225a1a7', 0, 0, 5, 'live', 'Someone asked which Muni to get', 'Beach Club is the one people bought first. Answer the question on camera with one reason per belt.', 'The guy who has the Muni page open and cannot pick.', 'Beach Club (Muni)', 'Reply to a comment', NULL, '["Someone asked which Muni to get. Real answer: the one that''s already the bestseller.", "You asked which one. Here''s mine and why.", "Beach Club sold first and I think I know why."]', '[{"label": "Open · 0 to 3s", "text": "The comment on screen, Beach Club held up."}, {"label": "Middle", "text": "Beach Club on in daylight, the braid up close. The other three in one hand, one reason each."}, {"label": "Close", "text": "\"Cut it once, it fits.\" Walk off."}]', 'Which Muni? Real answer:', 'Use a real question from your own comments if you have one.', 'Quote a review count.', NULL, 'A comment on screen: "which Muni should I get?" You hold up Beach Club.', '"Real answer:" then one reason per belt, ten seconds, the belt in your hand changing each time.', 'The reply-to-a-comment shape makes it feel like an answer, not an ad. SlideBelts used it for "which colour" and it was their best idea.', '[{"brand": "SlideBelts", "what": "\"Someone asked which color to get. Real answer:\" as the whole format.", "url": "https://app.tryatria.com/ad/m1303615761571131"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('2ce1e61ea72b9079', 'act_963898971023823', 'd37d5dabe5edc438', 1, 3, 6, 'live', 'Let''s see how long it takes him to notice', 'She gives him the belt and the whole video waits for the beat where he finds the marker in the buckle.', 'Partners who film each other. The golf-widow audience.', 'Any Muni or gator belt, in the box', 'Reaction', NULL, '["Y''all, I just bought my husband a golf belt. Let''s see how long it takes him to notice what the buckle does.", "He thinks it''s just a belt.", "Golf widow here. I got him something for his Wednesday league."]', '[{"label": "Open · 0 to 3s", "text": "Her setup line to camera, box in hand."}, {"label": "Middle", "text": "Hand it over. Hold on his face. Let him talk."}, {"label": "Close", "text": "His real line when the marker comes off. Cut there."}]', 'Let''s see how long it takes him', 'One continuous take. The wait is the video.', 'Tell him beforehand.', NULL, 'Her to camera holding the box, him not in frame yet. "Let''s see how long it takes him to notice."', 'He says "nice belt", puts it on, keeps talking, then finds the marker. "Wait a second."', 'The best gift video in golf right now is a wife with a phone doing exactly this for a polo brand: 192 days running, rank 1 of 329 ads. The viewer waits for one beat, so they stay.', '[{"brand": "Bogey Bros", "what": "The exact format, word for word: \"Let''s see how long it takes him to realize it.\"", "url": "https://app.tryatria.com/ad/m1859794814679897"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('78373410577fb33d', 'act_963898971023823', 'd37d5dabe5edc438', 0, 0, 7, 'live', 'The gift he won''t buy himself', 'Most golfers never spend a hundred dollars on a belt, which is exactly why it is the gift he wears every round.', 'Wives, girlfriends, adult kids.', 'Gator or ostrich belt in the box', 'Voiceover', NULL, '["He''ll never spend a hundred dollars on a belt. So I did.", "The golf gift he would never buy himself.", "What I got the golfer who has everything."]', '[{"label": "Open · 0 to 3s", "text": "The box on the counter, lid off, every piece visible."}, {"label": "Middle", "text": "He opens it. Camera on his face, not the belt."}, {"label": "Close", "text": "Him on the course that weekend. \"He hasn''t taken it off.\""}]', 'The gift he won''t buy himself', 'Keep the camera on his face.', 'Show the price in the first second. This one is about the reaction.', NULL, 'The Dartee box on the kitchen counter, her hands only, lid coming off so the whole kit shows.', 'His face when the marker comes off the buckle. Then him on the course that weekend.', '"A gift you''ll actually use, not another gadget collecting dust in a drawer" is the line the best belt gift ad runs on. Ours already works as a static.', '[{"brand": "Buckley Belts", "what": "The gift-you-actually-use line, as a voiceover over the box.", "url": "https://app.tryatria.com/ad/m1731415471213048"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '4f446e0b744e13d9', 'act_963898971023823', '78373410577fb33d', 'meta', '120232222230200741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120232222230200741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='78373410577fb33d' AND ad_id='120232222230200741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('e645acfe4e15fdd0', 'act_963898971023823', 'd37d5dabe5edc438', 0, 0, 8, 'live', 'I don''t know his waist size. Didn''t matter.', 'You cannot get the size wrong, because you cut it once. Every relative who bought the wrong glove size will get this.', 'Gift buyers afraid of sizing.', 'Any Dartee belt', 'Demo', NULL, '["I don''t know his waist size. Didn''t matter.", "The only golf gift you can''t get the size wrong on.", "Someone bought my husband a large glove. He is not a large. This belt fixes that problem."]', '[{"label": "Open · 0 to 3s", "text": "The belt next to his trousers, the line."}, {"label": "Middle", "text": "Measure with the card, cut, buckle on."}, {"label": "Close", "text": "A few clicks tighter, a few looser. \"Up to 46 inches.\""}]', 'No size? No problem.', 'Measure on camera before cutting.', 'Say it fits any size. It fits up to 46 inches.', NULL, 'Her holding the belt next to a pair of his trousers. "I had no idea what size he wears."', 'The sizing card, the scissors, the cut, the click. Four quick beats.', 'The number one complaint about golf gifts on the forums is the wrong size. Cut-to-fit answers it in four beats.', '[{"brand": "Anson Belt", "what": "The creator cutting the belt and saying \"cut the belt, reapply the buckle and boom\".", "url": "https://app.tryatria.com/ad/m1622172212779618"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('5dba70bdee185156', 'act_963898971023823', 'd37d5dabe5edc438', 0, 0, 9, 'live', 'There is nothing golf related he needs', 'He has every club and ball already. The belt is the one thing he uses every round and does not own.', 'Partners of serious golfers.', 'Any Dartee belt', 'Talking head', NULL, '["There is nothing golf related he needs. I checked.", "He has every club. He has one belt and it''s from his wedding.", "I''m not buying him another ball retriever and a mug."]', '[{"label": "Open · 0 to 3s", "text": "The gear pile, her pointing."}, {"label": "Middle", "text": "The old belt, then the Dartee box."}, {"label": "Close", "text": "Him wearing it. Pockets empty."}]', 'He has everything. Except this.', 'Be funny about his gear pile.', 'Make him look dumb. He is the hero.', NULL, 'Her in his golf closet or the garage, pointing at the pile of gear.', '"Then I noticed his belt." Cut to his old belt, holes and all.', '"There is nothing golf related he needs nor wants" is a real line from a golf wife, and the junk-gift drawer is a real thing. Naming it buys the next ten seconds.', '[{"brand": "Buckley Belts", "what": "A belt sold as the gift that is not another gadget.", "url": "https://app.tryatria.com/ad/m1731415471213048"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '72f38c1257748d9b', 'act_963898971023823', '5dba70bdee185156', 'meta', '120232222230200741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120232222230200741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='5dba70bdee185156' AND ad_id='120232222230200741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('82efbb9adf7cccf9', 'act_963898971023823', 'd37d5dabe5edc438', 0, 0, 10, 'live', 'Stocking stuffers that clip onto his belt', 'Small gifts under $25 that all attach to the belt he already has.', 'Buyers who already gave the belt, or want something small.', 'Ball markers ($9.99), Dar-Tees, the Dartee glove', 'Flat lay', NULL, '["Golf stocking stuffers, and they all clip onto his belt.", "Three small golf gifts he''ll actually use.", "Custom markers are the easiest golf gift to get right. Here''s why."]', '[{"label": "Open · 0 to 3s", "text": "The stocking, the hand, the three items."}, {"label": "Middle", "text": "Each item onto the belt, snap, slide, clip."}, {"label": "Close", "text": "The loaded belt, worn."}]', 'Stocking stuffers that stay on the belt', 'Say each price as it appears.', 'Make the hat the hero.', NULL, 'A stocking on the mantle. A hand pulls out a marker, a tee pack, a glove.', 'Each one clips onto the belt in a second: marker to buckle, tees to holder, glove to clip.', 'One small product, one job, two seconds each. The Pins and Aces hat ad does exactly that with a magnet and runs on it.', '[{"brand": "Pins and Aces", "what": "Hold the small thing to the lens, then turn it to show the one job it does.", "url": "https://app.tryatria.com/ad/m1763143554895344"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('cce091d188a5ee76', 'act_963898971023823', 'd37d5dabe5edc438', 0, 0, 11, 'live', 'Black Friday, the whole foursome', 'One order covers your dad, your brother and your two buddies, and the site gives you a better price at two and three belts.', 'The guy who buys for his group.', 'Any belts, 2 or more', 'Flat lay', NULL, '["Black Friday plan: one belt for everyone in my foursome.", "Every golfer on my list. One order.", "Dad gets the gator. My brother gets the one named Tire Tracks. Don''t ask."]', '[{"label": "Open · 0 to 3s", "text": "The four boxes, the four names."}, {"label": "Middle", "text": "The four reasons, one belt in hand each time."}, {"label": "Close", "text": "Say the Black Friday offer exactly as the site shows it that day."}]', 'The whole foursome', 'Read the offer off the site on the day.', 'Invent a discount. The Black Friday offer is not set yet.', NULL, 'Four boxes on the table, a name written on each.', 'One line per name on why that colour. The viewer wants to hear all four.', 'Our two-for-one offer video was the best return in the account in September. The buddy shape works with or without the offer.', '[{"brand": "Buckley Belts", "what": "Belts sold as a 3-pack for gifting.", "url": "https://app.tryatria.com/ad/m1731415471213048"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '4d2ea10e37f3eb2c', 'act_963898971023823', 'cce091d188a5ee76', 'meta', '120246488431680741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120246488431680741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='cce091d188a5ee76' AND ad_id='120246488431680741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('30615996b81220b6', 'act_963898971023823', 'd37d5dabe5edc438', 0, 0, 12, 'live', 'The gift that left the drawer', 'Every novelty golf gift ends up in a drawer. The belt is the one that gets used every round.', 'Gift buyers burned by joke gifts.', 'Any Dartee belt', 'Voiceover', NULL, '["Every golf gift he got last year is in this drawer.", "The ball stamper didn''t work. The headcover fell off. The joke book wasn''t funny.", "This is the one golf gift that left the drawer."]', '[{"label": "Open · 0 to 3s", "text": "The drawer, the junk."}, {"label": "Middle", "text": "Three weekends, three dates, same belt."}, {"label": "Close", "text": "The belt on, pockets empty."}]', 'The gift that earns bag space', 'Use real junk gifts from your own house.', 'Name another brand''s product.', NULL, 'A drawer of unused golf gifts pulled open: ball stamper, novelty headcover, joke book.', 'Close the drawer. Cut to the belt on the course three weekends in a row, date on screen each time.', 'Golfers on the forums list the worst presents by name: the ball stamper, the emoji headcover, the joke book. Dartee''s own blog uses "earns bag space".', '[{"brand": "Buckley Belts", "what": "\"A gift you''ll actually use\" as the whole pitch.", "url": "https://app.tryatria.com/ad/m1731415471213048"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '367aa26dbeee4a2f', 'act_963898971023823', '30615996b81220b6', 'meta', '120232222230200741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120232222230200741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='30615996b81220b6' AND ad_id='120232222230200741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('8c572875833e5479', 'act_963898971023823', '3396a97da88d8e0d', 1, 4, 13, 'live', 'Belt companies think we''re idiots', 'Holes are a bad system everybody accepted. The ratchet fixes it, and the buckle holds your marker on top.', 'Anyone wearing an old leather belt on the course.', 'Any Dartee belt', 'Talking head', NULL, '["Belt companies think we''re idiots. Here''s a few holes, good luck.", "One hole too tight, one hole too loose. How did we all agree to this?", "I punched a new hole in my belt in a car park once. Never again."]', '[{"label": "Open · 0 to 3s", "text": "The old belt held up, the holes to the lens, the rant starts."}, {"label": "Middle", "text": "The cut to the Dartee. Three clicks. The marker snap."}, {"label": "Close", "text": "\"None of this is revolutionary. It''s how a golf belt should have worked.\""}]', 'Here''s a few holes. Good luck.', 'One take, no music. Keep it a rant.', 'Copy Anson''s lines word for word. Keep the beat, change the words.', NULL, 'You, to camera, holding up an old belt with a row of stretched or homemade holes.', '"Then I found this." Hard cut to the Dartee: click, click, click, marker snaps on.', 'Anson relaunched its whole account in September and the creator rants about holes are its best new format. The "then I found this" cut is the beat that holds people.', '[{"brand": "Anson Belt", "what": "The whole shape: the rant, the holes, \"then I found this\".", "url": "https://app.tryatria.com/ad/m1980515675946741"}, {"brand": "Anson Belt", "what": "\"Holes in my belt get all stretched out and the whole thing starts looking like a sloppy mess.\"", "url": "https://app.tryatria.com/ad/m1730602779068185"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '6ca37943e84d67c4', 'act_963898971023823', '8c572875833e5479', 'meta', '120238662506390741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120238662506390741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='8c572875833e5479' AND ad_id='120238662506390741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('0ee3fba11473ed66', 'act_963898971023823', '3396a97da88d8e0d', 0, 0, 14, 'live', 'No, I didn''t just ruin a hundred-dollar belt', 'You cut the strap once and the ratchet covers every eighth of an inch after that, so the belt changes with you.', 'Guys whose weight goes up and down.', 'Any Dartee belt', 'Demo', NULL, '["No, I didn''t just ruin a hundred-dollar belt.", "I lost 20 pounds and my belt had four homemade holes. Not this one.", "Measure, cut once, click. Just don''t put the weight back on."]', '[{"label": "Open · 0 to 3s", "text": "The cut."}, {"label": "Middle", "text": "The card, the buckle going on, the clicks."}, {"label": "Close", "text": "The joke line, deadpan."}]', 'Cut once. Clicks every 1/8 inch.', 'Measure with the card on camera.', 'Cut without measuring. And do not promise a free replacement if it is cut too short.', NULL, 'Scissors on the strap, mid-cut, before anyone talks.', '"No, I didn''t just ruin it." Then the sizing card, the buckle, the clicks.', 'A cold open on scissors is a pattern interrupt that costs nothing, and the weight joke is the rehook Anson''s creator closes on.', '[{"brand": "Anson Belt", "what": "The weight-loss story and the joke: \"just make sure you don''t put the weight back on\".", "url": "https://app.tryatria.com/ad/m1622172212779618"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('a207db9f212d058c', 'act_963898971023823', '3396a97da88d8e0d', 0, 0, 15, 'live', 'Same belt since 8th grade', 'Talk to the guy who has never once thought about his belt.', 'The golfer whose belt came with his first suit.', 'Any Dartee belt', 'Side by side', NULL, '["You''ve been wearing the same belt since 8th grade. On the golf course.", "If your belt only holds up your pants, it''s doing one job. This one does four.", "Your belt came with your prom suit. Admit it."]', '[{"label": "Open · 0 to 3s", "text": "The old belt tip, up to your face."}, {"label": "Middle", "text": "The checklist: holds pants, marker, tees, glove, no holes."}, {"label": "Close", "text": "Old belt in the drawer."}]', 'Your belt vs a golf belt', 'Use your actual old belt.', 'Explain the magnet. Show it.', NULL, 'Close-up of a cracked, curled old belt tip. Tilt up to your face.', 'Side by side at the hip: old belt left, Dartee right, with the checklist ticking on screen.', 'Naming the viewer ("you''ve been wearing the same belt since 8th grade") works better than naming the product. Groove runs it in ten seconds.', '[{"brand": "Groove Life", "what": "\"Guys you''ve been wearing the same belt since 8th grade.\"", "url": "https://app.tryatria.com/ad/m1009061838517746"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '1db017da72e64424', 'act_963898971023823', 'a207db9f212d058c', 'meta', '120237391091280741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120237391091280741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='a207db9f212d058c' AND ad_id='120237391091280741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('fb163c7f471a2f44', 'act_963898971023823', '3396a97da88d8e0d', 0, 0, 16, 'live', 'You definitely don''t need another belt', 'You do not need more belts. You need one that does the job on the course.', 'Guys with a drawer of belts.', 'Any Dartee belt', 'Pattern interrupt', NULL, '["You definitely don''t need another belt.", "I own eleven belts. Zero of them are golf belts.", "This is what I think of my old golf belt."]', '[{"label": "Open · 0 to 3s", "text": "The stunt with the old belt."}, {"label": "Middle", "text": "The Dartee on, marker off the buckle on a real green."}, {"label": "Close", "text": "Pockets turned out, empty."}]', 'Pockets optional.', 'Find your own stunt.', 'Reuse the toilet.', NULL, 'Do something surprising with the old belt in the first second: bin, lake, hand it to the dog. Ours used a toilet.', '"You don''t need another belt. You need a better one." Cut to the Dartee on, marker off the buckle on a green.', 'Nobody else in the belt category does a physical pattern interrupt. Ours still runs at 2.7x a year on.', '[]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'e80b374c5f7a4267', 'act_963898971023823', 'fb163c7f471a2f44', 'meta', '120240009827450741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120240009827450741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='fb163c7f471a2f44' AND ad_id='120240009827450741');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'e563ee1eaac9165e', 'act_963898971023823', 'fb163c7f471a2f44', 'meta', '120240009817870741', 1, 2 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120240009817870741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='fb163c7f471a2f44' AND ad_id='120240009817870741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('183d3184b238a563', 'act_963898971023823', '82cb5e3f54740409', 0, 0, 17, 'live', '$100 for a golf belt?', 'Say the price first, then open the box and count what you get.', 'Guys who think a belt should cost twenty bucks.', 'Gator or ostrich belt ($99.99)', 'Price reveal', NULL, '["A hundred dollars for a golf belt? Hear me out.", "I wasn''t ready to pay this for a belt. Then I opened it.", "My wife asked why I spent a hundred bucks on a belt. This is the answer."]', '[{"label": "Open · 0 to 3s", "text": "The price on screen, the closed box."}, {"label": "Middle", "text": "The box flat, the one-breath count."}, {"label": "Close", "text": "Worn on the course. \"Now it makes sense.\""}]', '$100 for a golf belt?', 'Say the real price of the belt in your hand.', 'Skip the box. The count is the proof.', NULL, 'Text on screen "$100 for a golf belt?" over a closed box. Your eyebrows up.', 'Box opened flat, every piece named in one breath: belt, buckle, marker, tee holder, glove holder, sizing card.', 'Our best cost-per-sale ad ever says the price objection out loud first. The TikTok Shop creators do the same with bags: "I really wasn''t ready to pay that kind of money".', '[{"brand": "Pins and Aces", "what": "The creator who says the price first, then why it was worth it.", "url": "https://app.tryatria.com/ad/m1067339445915203"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '4c165559b40ec8e4', 'act_963898971023823', '183d3184b238a563', 'meta', '120239237680840741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120239237680840741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='183d3184b238a563' AND ad_id='120239237680840741');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'a696f4769c603f9b', 'act_963898971023823', '183d3184b238a563', 'meta', '120237392010370741', 1, 2 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120237392010370741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='183d3184b238a563' AND ad_id='120237392010370741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('e77757fe3fb7b108', 'act_963898971023823', '82cb5e3f54740409', 0, 0, 18, 'live', '50 Shades of Gator, in daylight', 'New embossed colours just dropped. The texture is the hook and the name is the rehook.', 'The drop collector.', '50 Shades of Gator, Bone Dry, Purple Reign (new)', 'Texture reveal', NULL, '["This one''s called 50 Shades of Gator and I''m not explaining the name.", "New gator just dropped. Look at it in the sun.", "Bone Dry. New. Already on my belt."]', '[{"label": "Open · 0 to 3s", "text": "The texture, tight, in the sun."}, {"label": "Middle", "text": "The name, the box, the matching marker."}, {"label": "Close", "text": "On the first tee. Someone notices."}]', 'New: 50 Shades of Gator', 'Film texture outdoors.', 'Say real alligator, crocodile or ostrich. It is embossed leather.', NULL, 'Slow push into the embossed scales in sunlight. No face yet.', 'Pull back, say the name, say "embossed", say it just came out.', 'Anson launched its ostrich line by holding it to the lens in daylight and naming it. Texture is a visual hook on its own.', '[{"brand": "Anson Belt", "what": "The founder holds the new embossed line to the lens, names the colour, says it just came out.", "url": "https://app.tryatria.com/ad/m1102646692210777"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '5f9ffafa6fe49386', 'act_963898971023823', 'e77757fe3fb7b108', 'meta', '120246116810010741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120246116810010741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='e77757fe3fb7b108' AND ad_id='120246116810010741');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '4ece8e27b2543b88', 'act_963898971023823', 'e77757fe3fb7b108', 'meta', '120245845649450741', 1, 2 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120245845649450741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='e77757fe3fb7b108' AND ad_id='120245845649450741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('afb09bb5f6e578ba', 'act_963898971023823', '82cb5e3f54740409', 0, 0, 19, 'live', 'White belt. Guess my handicap.', 'Fashion people say the white belt is over, which is exactly why the joke still lands.', 'Guys who get the white-belt handicap joke.', 'Storm Trooper White, Albino Gator', 'Fit check', NULL, '["The fashion guys say the white belt''s best days are behind it. My handicap agrees.", "White belt. Guess my handicap.", "When I wear the white belt my buddies just hand me the money."]', '[{"label": "Open · 0 to 3s", "text": "The tilt, shoes to belt."}, {"label": "Middle", "text": "The reaction, the bill."}, {"label": "Close", "text": "The real number."}]', 'White belt. Guess my handicap.', 'Let the joke land on you.', 'Say the belt helps your score.', NULL, 'Tilt up from white shoes to a white belt on the first tee.', 'A buddy hands over a bill before the round. Then your real handicap on screen.', 'Self-deprecation disarms the ad read. "Shoot a hundred and still get compliments" is the line Pins and Aces runs on.', '[{"brand": "Pins and Aces", "what": "\"Name a golf brand where you can shoot a hundred and still get compliments.\"", "url": "https://app.tryatria.com/ad/m2302755733814212"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('ef8b0aa7baf7c10c', 'act_963898971023823', '82cb5e3f54740409', 0, 0, 20, 'live', 'Counting how many times my group asks about my belt', 'Wear it one round and count how many times the group asks where you got it.', 'The guy who likes being the one with the good gear.', 'Gator, ostrich, any', 'Running count', NULL, '["Counting how many times my group asks about my belt today.", "I got asked about this belt four times in one round.", "Your buddies are going to ask. Here''s proof."]', '[{"label": "Open · 0 to 3s", "text": "The first point, the 1 on screen."}, {"label": "Middle", "text": "Marker off the buckle, glove clip, tee from the holder, each with a new ask and a new number."}, {"label": "Close", "text": "The final count. \"They always want to know where.\""}]', 'Times asked about my belt: 4', 'Let the real questions happen.', 'Script the buddies. It shows.', NULL, 'Hole 1, a buddy points at the belt. A big "1" lands on screen.', 'The count climbs with each cut. The viewer waits for the final number.', 'A number that climbs is the simplest retention device there is. The compliment is also the thing our reviews say most.', '[{"brand": "Pins and Aces", "what": "Compliments as the pitch, said by a creator who admits he is not good.", "url": "https://app.tryatria.com/ad/m2302755733814212"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '058bc2ffa1b63457', 'act_963898971023823', 'ef8b0aa7baf7c10c', 'meta', '120245960128970741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120245960128970741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='ef8b0aa7baf7c10c' AND ad_id='120245960128970741');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '188e4de101abd8e7', 'act_963898971023823', 'ef8b0aa7baf7c10c', 'meta', '120246116810010741', 1, 2 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120246116810010741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='ef8b0aa7baf7c10c' AND ad_id='120246116810010741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('e027b476447bae45', 'act_963898971023823', '82cb5e3f54740409', 0, 0, 21, 'live', 'Did I mention it''s the #1 belt in golf', 'Say the claim, then make fun of saying it, so it never sounds like an ad.', 'Golfers allergic to ad reads.', 'Any Dartee belt', 'Skit', NULL, '["Did I mention this is the number one belt in golf?", "It''s the number one belt in golf. I''m going to keep saying it.", "The number one belt in golf. Sorry. I can''t stop."]', '[{"label": "Open · 0 to 3s", "text": "The cart, the deadpan line."}, {"label": "Middle", "text": "Three repeats, three uses of the belt."}, {"label": "Close", "text": "\"Fine, I''ll stop.\" Then one more."}]', '#1 belt in golf (again)', 'Keep it under 20 seconds.', 'Add a review count or a star rating.', NULL, 'You, deadpan to camera on the cart: "Did I mention this is the number one belt in golf?"', 'You say it again on the green, again at the bar. Each time the marker or a tee is doing something.', 'Groove runs a 15-second ad that repeats "best belt in the world" three times and mocks itself for it. It sits at rank 3 of 72.', '[{"brand": "Groove Life", "what": "\"Did I mention the groove belt is the best belt in the world? I can''t stop doing this.\"", "url": "https://app.tryatria.com/ad/m957958250525755"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '652ec8f62c9da066', 'act_963898971023823', 'e027b476447bae45', 'meta', '120239960847110741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120239960847110741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='e027b476447bae45' AND ad_id='120239960847110741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('40f482bf983534e2', 'act_963898971023823', '4cc063cb926a54e3', 1, 5, 22, 'live', '18 holes. Not touching my pockets once.', 'The video the category does not have: a real round, start to finish, the belt doing its three jobs without anyone explaining them.', 'Anyone seeing Dartee for the first time.', 'Any Dartee belt', 'On-course POV', NULL, '["18 holes. I''m not touching my pockets once.", "I''m going to play a full round and never explain this belt.", "Watch the belt, not me."]', '[{"label": "Open · 0 to 3s", "text": "Hole 1, the setting, the marker."}, {"label": "Middle", "text": "Marker off and on, tee from the holder, glove clipped after a shot, a bunker, a crouch to read a putt."}, {"label": "Close", "text": "Hole 18, same ratchet setting, marker still there."}]', 'Hole 1 / Hole 18. Pockets touched: 0', 'Real swings, real greens. Set it to fit, not tight.', 'Over-tighten it. That is how it slips.', NULL, 'Hole 1 tee box. Set the ratchet, show the marker in the buckle. No words yet.', 'An on-screen counter: holes played, times the pocket was touched (zero). It ticks all round.', 'Sunday Golf''s plain first-outing video has run for a year. Nobody has made the belt version. The slot is open.', '[{"brand": "Sunday Golf", "what": "A plain \"first time out with it\" video that never stopped running.", "url": "https://app.tryatria.com/ad/m1432948334462951"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '887b7f8dcc5e81d6', 'act_963898971023823', '40f482bf983534e2', 'meta', '120237392010370741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120237392010370741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='40f482bf983534e2' AND ad_id='120237392010370741');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT 'eb6b3f976fa33cf4', 'act_963898971023823', '40f482bf983534e2', 'meta', '120246517338760741', 1, 2 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120246517338760741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='40f482bf983534e2' AND ad_id='120246517338760741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('983effaa10d19f0b', 'act_963898971023823', '4cc063cb926a54e3', 0, 0, 23, 'live', 'Four balls, one marker. Mine.', 'In a scramble every ball gets marked and you are the one with a marker ready while everybody else pats pockets.', 'The charity-outing and member-guest regular.', 'Any Dartee belt', 'On-course POV', NULL, '["Scramble rule: always putt after the guy with the Dartee belt.", "Four balls, one marker. Mine.", "Watch what happens when four guys need a marker at once."]', '[{"label": "Open · 0 to 3s", "text": "The green, the four balls, the patting."}, {"label": "Middle", "text": "The two marks, snap and snap."}, {"label": "Close", "text": "Team photo with the flag."}]', 'The guy with the marker is the MVP', 'Film a real outing. The carts lined up sell it.', 'Explain the magnet. Let it snap.', NULL, 'Four balls on the green. Three guys patting their pockets.', 'Marker off the buckle, mark, snap back. Then again for the next ball, faster.', 'The hand on each piece as it is used, not described, is the shape the best WITB creators use.', '[{"brand": "Pins and Aces", "what": "Hand on each feature as it is used.", "url": "https://app.tryatria.com/ad/m1651267819953460"}]');
