INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('4a306ea3b188007e', 'act_963898971023823', '4cc063cb926a54e3', 0, 0, 24, 'live', 'Stop asking your buddy for a marker', 'The marker lives on the buckle so you never dig for it while the group waits.', 'Golfers who dig for a marker every green.', 'Any Dartee belt', 'On-course POV', NULL, '["Stop asking your buddy for a ball marker.", "Mark, putt, snap it back. Done.", "Standing in my buddy''s line digging for a marker. Not anymore."]', '[{"label": "Open · 0 to 3s", "text": "The POV, hand to the buckle."}, {"label": "Middle", "text": "The mark and the putt."}, {"label": "Close", "text": "Snap, walk off."}]', 'Marker on the buckle', 'Film on a real green from your eye line.', 'Film the buckle on a table. We have those.', NULL, 'Eye-line POV on the green. Your hand goes to the buckle, not the pocket.', 'Mark, putt, snap it back, all in one shot with the sound up.', 'Anson''s number one ad opens on the click. The marker snap is Dartee''s version and it is louder.', '[{"brand": "Anson Belt", "what": "The click as the hook: \"once I put that on I heard the click\".", "url": "https://app.tryatria.com/ad/m2028969921084508"}]');
INSERT INTO p_amb_proof (id, act_id, angle_id, kind, ad_id, shown, sort) SELECT '0f34451ef1a7ffd7', 'act_963898971023823', '4a306ea3b188007e', 'meta', '120242460444050741', 1, 1 WHERE EXISTS (SELECT 1 FROM ads WHERE act_id='act_963898971023823' AND ad_id='120242460444050741') AND NOT EXISTS (SELECT 1 FROM p_amb_proof WHERE angle_id='4a306ea3b188007e' AND ad_id='120242460444050741');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('5a46c105fb935937', 'act_963898971023823', '4cc063cb926a54e3', 0, 0, 25, 'live', 'Where does your glove go between shots?', 'Gloves fall out of back pockets and get left in carts. On the belt it stays put and dries out.', 'Anyone who has lost a glove mid-round.', 'Any Dartee belt', 'Side by side', NULL, '["My glove used to live in my back pocket. Here''s where it lives now.", "I lost two gloves in one round. Never again.", "Where does your glove go between shots?"]', '[{"label": "Open · 0 to 3s", "text": "The drop."}, {"label": "Middle", "text": "Glove off after a shot, clipped on in one move."}, {"label": "Close", "text": "Hole 18, still there."}]', '"It''s always one thing." / Back pocket vs belt', 'Use a real lost glove if you have one.', 'Over-explain the clip.', NULL, 'A glove flops out of your back pocket as you walk off the green and lands on the fringe.', 'Same walk, glove clipped on the belt, nothing falls. Then the forum line on screen.', '"I''ll realize that my glove is still in my back pocket. It''s always one thing." is a real golfer''s line. Show it, then fix it.', '[{"brand": "Pins and Aces", "what": "Turn the product to show the magnet doing its job.", "url": "https://app.tryatria.com/ad/m1763143554895344"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('f3e4e82da9eeb565', 'act_963898971023823', '4cc063cb926a54e3', 0, 0, 26, 'live', 'If you keep tees in your front pocket, you''ve been stabbed today', 'Tees in a pocket jab you all day. Tees on the belt never do.', 'Every golfer who keeps tees in a front pocket.', 'Any Dartee belt', 'Skit', NULL, '["If you keep tees in your front pocket, you''ve been stabbed by one today.", "Aren''t you worried it''ll puncture your valuables?", "Stabbed by a tee for the last time."]', '[{"label": "Open · 0 to 3s", "text": "The flinch."}, {"label": "Middle", "text": "The pocket dump."}, {"label": "Close", "text": "Tee out of the holder without looking, next box."}]', 'Tees go on the belt', 'Make the flinch real.', 'Turn it into a feature list afterwards.', NULL, 'Hand into the pocket, a big flinch, out comes a broken tee.', 'Empty the pocket onto the cart seat: tees, a coin, lint, a pencil. Then the holder with two tees.', 'The flinch is a visual hook with no product in it, and the pocket dump is a reveal. Both are things people have done.', '[{"brand": "Anson Belt", "what": "A pain said in plain words first, the product second.", "url": "https://app.tryatria.com/ad/m1980515675946741"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('37796e84c85ea873', 'act_963898971023823', '4cc063cb926a54e3', 0, 0, 27, 'live', 'Packing for four rounds. One belt.', 'On a trip you pack four outfits and one belt, because it holds the marker, tees and glove for every round.', 'The buddy-trip organiser.', 'Any Dartee belt', 'Flat lay', NULL, '["Packing for four rounds in three days. One belt.", "The one thing I pack first for a golf trip.", "Four outfits, one belt, and I''m not touching my pockets all weekend."]', '[{"label": "Open · 0 to 3s", "text": "The suitcase, the stack, the belt on top."}, {"label": "Middle", "text": "The load."}, {"label": "Close", "text": "First tee at the destination, course name on screen."}]', '4 rounds. 1 belt.', 'Show the tee sheet or the course sign.', 'Mention a free-shipping amount.', NULL, 'Suitcase open on the bed, four outfits stacked, the belt dropped on top last.', 'Load the belt on camera: marker in, two tees in the holder, glove clipped. Everything else into the bag.', 'A packing video is a flat lay with a reason, and the load is a demo nobody has to explain.', '[{"brand": "Sunday Golf", "what": "One product, one real trip, said plainly.", "url": "https://app.tryatria.com/ad/m1432948334462951"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('4e345d758496bf3a', 'act_963898971023823', '4cc063cb926a54e3', 0, 0, 28, 'live', 'If you can still see the flag, you can still play', 'The last nine of the year, named for the belt, filmed at sunset.', 'Twilight-rate golfers squeezing in the last good weeks.', 'The Last Loop (Muni)', 'Day in the life', NULL, '["If you can still see the flag, you can still play. Those are the rules.", "Last loop of the year. Wearing the belt named for it.", "First one out, last one in."]', '[{"label": "Open · 0 to 3s", "text": "Sunset, the walk off the cart."}, {"label": "Middle", "text": "Marker off on a dark green, phone torch on the ball."}, {"label": "Close", "text": "The clubhouse lights."}]', 'The Last Loop', 'Use the belt''s own name story from the product page.', 'Add a spec list over the sunset.', NULL, 'Low sun, long shadows, walking off the cart with the belt in frame.', '"If you can still see the flag, you can still play." said on the 7th tee as it gets dark.', 'The belt has a name and a story on its own product page. Reading it on the 7th tee at dusk is the whole video.', '[{"brand": "Sunday Golf", "what": "One product, one outing, no spec list, 576 days.", "url": "https://app.tryatria.com/ad/m581226258294725"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('6bc265c1819b7c15', 'act_963898971023823', '4cc063cb926a54e3', 0, 0, 29, 'live', 'Gave my buddy this belt on the first tee. Told him nothing.', 'Hand a Dartee to a buddy with no explanation and film him working it out.', 'Buddies or a starter who has never seen one.', 'Any Dartee belt', 'Reaction', NULL, '["Gave my buddy this belt on the first tee. Told him nothing.", "First time he''s seen it. No script.", "Let''s see how long it takes him to find the marker."]', '[{"label": "Open · 0 to 3s", "text": "The handoff."}, {"label": "Middle", "text": "Him finding the marker, then the holders."}, {"label": "Close", "text": "His verdict after one hole."}]', 'First time wearing it', 'Let him talk.', 'Feed him lines.', NULL, 'A belt handed over on the tee. He turns it over in his hands.', 'The moment he finds the marker in the buckle. "Oh, that''s actually smart."', 'The wait for the realisation is the same beat as the wife gift video, with a buddy. Unscripted reactions are the one thing that never reads as an ad.', '[{"brand": "Bogey Bros", "what": "The wait for \"Wait a second.\"", "url": "https://app.tryatria.com/ad/m1859794814679897"}]');
INSERT INTO p_amb_angle (id, act_id, section_id, hot, hot_sort, sort, status, title, argument, who, products, format, lever, openers_json, shots_json, on_screen, do_text, dont_text, trend, visual_hook, rehook, why, inspo_json) VALUES ('10c2b13f7f8ce9cd', 'act_963898971023823', '4cc063cb926a54e3', 0, 0, 30, 'live', 'What''s on my belt', 'What''s in the bag, moved to the belt: one piece at a time, each one used, not described.', 'Golfers who watch WITB videos.', 'Any Dartee belt', 'On-course POV', NULL, '["Forget what''s in the bag. What''s on my belt.", "Everything I need for 18 holes is on my hip.", "I might suck at golf but my belt doesn''t."]', '[{"label": "Open · 0 to 3s", "text": "Hip height, the line, the hand on the buckle."}, {"label": "Middle", "text": "The four uses, two seconds each."}, {"label": "Close", "text": "Pull out to the full fit on the tee."}]', 'What''s on my belt', 'Name it, use it, move on.', 'Read the product page.', NULL, 'Tight on the hip. "What''s on my belt." Hand touches the buckle.', 'Each piece gets two seconds and one use: marker (mark), tees (tee up), glove (clip), ratchet (click).', 'The WITB creator at Pins and Aces opens with "i might suck at golf but this bag doesn''t" and touches each pocket. Same shape, smaller product.', '[{"brand": "Pins and Aces", "what": "Hand on each feature, self-deprecating opener.", "url": "https://app.tryatria.com/ad/m1651267819953460"}]');
