UPDATE p_amb_brand SET display_name='Dartee Golf', intro='Dartee is the belt that holds your marker, your tees and your glove, so your pockets stay empty. We want videos that look like a real round with your buddies, not a product demo. Pick one idea, do the first second the way it says, and submit it on TRYBE like always.', about='A golf belt with a magnetic buckle that holds your ball marker, plus a tee holder and a glove holder that slide anywhere on the strap. Ratchet, no holes, clicks every 1/8 inch. You cut it once and it fits up to 46 inches. New this fall: the Muni line (The Last Loop, Beach Club, Weekend Warrior, Tire Tracks) at $79.99, plus 50 Shades of Gator, Bone Dry and Purple Reign. Gator and ostrich belts are embossed leather at $99.99.', audience='Guys who play most weekends and like being the one with the good gear. From November it is also the wives, girlfriends and kids shopping for the golfer who already has everything.', accent='#0F7F73', avoid_json='[{"title": "Holding the belt up and naming its features", "why": "Most of what we get. It sells the least of anything we run. Use the belt in a real round instead."}, {"title": "A buckle close-up on a table with \"a ball marker on the buckle?\"", "why": "We have plenty. Show the marker coming off on a real green, with the sound up."}, {"title": "Talking to the camera while nothing happens", "why": "Your hands have to be doing something in the first second: cutting, clipping, marking, dropping the old belt."}, {"title": "Reading the product page (\"premium\", \"dialed\", \"flow state\")", "why": "Say one thing the belt does and show the rest. Nobody stops scrolling for a spec list."}, {"title": "A hat as the star", "why": "Hat videos do not sell for us. The belt is the hero."}, {"title": "Score promises and fake transformations", "why": "The fastest way to look like an infomercial. A joke about your handicap is fine. A claim is not."}]', rules_json='["You can say: \"the #1 belt in golf\", \"patented magnetic buckle\", \"fits any waist up to 46 inches\", \"clicks every 1/8 inch\", \"lifetime warranty on the buckle and ratchet\", \"30-day money-back guarantee\".", "Don''t quote a number of reviews, stars or customers. It never sounds natural in a video.", "Gator, croc and ostrich belts are embossed leather. Never say real alligator, crocodile or ostrich.", "The Muni belts: say braided. We are confirming whether to say stretch, so leave that word out for now.", "The fourth Muni belt is called Tire Tracks on the site today. Use the name the site shows.", "Never say the belt makes you play better. A joke that is obviously a joke (\"3 strokes minimum\") is fine.", "Only mention an offer that is live on the site the day you post. Don''t quote a free shipping amount.", "Cutting the strap: measure with the sizing card first, then cut once.", "Show the belt worn in at least one shot, with the marker in the buckle. Film vertical, sound on.", "Only film people who agreed to be in your video. If there is alcohol on screen, everyone is 21 or older."]', season_json='{"title": "Fall golf, then gift season", "until": "Nov 23", "line": "The last good rounds of the year, scrambles and buddy trips, and the new Muni belts. Gift shopping starts in early November, so film your gift videos NOW so they are live by Nov 1. Black Friday week is the biggest week we have.", "next": "Black Friday and Christmas gifting, from Nov 24", "highlight": ["10-06", "11-23"], "show_chart": true, "color": "#0F7F73", "cap": null, "mode": "custom", "custom": {"1": 14, "2": 14, "3": 19, "4": 22, "5": 32, "6": 32, "7": 28, "8": 28, "9": 28, "10": 36, "11": 34, "12": 36, "13": 30, "14": 36, "15": 60, "16": 30, "17": 22, "18": 20, "19": 23, "20": 23, "21": 30, "22": 30, "23": 36, "24": 42, "25": 40, "26": 26, "27": 24, "28": 26, "29": 26, "30": 25, "31": 25, "32": 26, "33": 28, "34": 32, "35": 26, "36": 30, "37": 30, "38": 28, "39": 25, "40": 23, "41": 23, "42": 25, "43": 26, "44": 27, "45": 30, "46": 40, "47": 48, "48": 100, "49": 85, "50": 76, "51": 72, "52": 45, "53": 16}}', guide_json='[{"title": "Your hands do something in the first second", "text": "Scissors on the strap, an old belt in the bin, a marker snapping onto the buckle. Then you can talk. Our best ad opens on a box lid coming off with the whole kit visible."}, {"title": "Let the belt make its noise", "text": "The click of the ratchet and the snap of the marker are your hook. Anson''s number one ad is a guy saying \"once I put that on I heard the click\". Ours is louder."}, {"title": "Say the thing people already think", "text": "\"$100 for a golf belt?\" and \"you definitely don''t need another belt\" were our best creator-style ads. Say the objection out loud, then answer it."}, {"title": "Give them one thing to wait for", "text": "A count that climbs, a buddy who has not noticed yet, a price that comes down. If the viewer is waiting for one beat, they stay. The wife filming \"let''s see how long it takes him to notice\" ran 192 days for another brand."}, {"title": "Change the picture at 3 seconds", "text": "Cut to a new place, a new person or a new angle before you have finished your first sentence. Old belt, then \"then I found this\", then the new one."}, {"title": "Use it, do not describe it", "text": "Mark the ball. Pull a tee. Clip the glove. Two seconds each. If you catch yourself listing features, stop and go do one."}, {"title": "Real round, real buddies", "text": "Film on the course with the group you actually play with. The questions they ask on camera are better than any line we write."}, {"title": "End on the belt being worn", "text": "Pockets turned out, marker on the buckle, walking to the next tee. Then the submit. No wrap-up speech."}]', updated_at=datetime('now') WHERE act_id='act_963898971023823';
